$('#files').addEventListener('change',()=>run(async()=>{const files=[...$('#files').files];if(!files.length)return;busy=true;let count=0;try{for(const file of files){if(file.size>150*1024*1024){toast(`${file.name}: larger than the 150 MB import limit.`);continue;}await store.saveTrack({id:crypto.randomUUID(),title:file.name.replace(/\.[^.]+$/,''),artist:'Local import',source:'local',bpm:0,start:0},file);count++;}tracks=await store.listTracks();await library5.refreshData();route='library';render();toast(`${count} audio file${count===1?'':'s'} stored on this device.`);}finally{busy=false;$('#files').value='';}}));
function bindGestures(){for(const el of $$('[data-wave],[data-platter]')){const isPlatter=el.dataset.platter!==undefined,i=+(isPlatter?el.dataset.platter:el.dataset.wave);let drag=null;el.addEventListener('pointerdown',e=>{if(locked){toast('Unlock to scrub or seek.');return;}if(!engine.decks[i].track||drag)return;e.preventDefault();el.setPointerCapture(e.pointerId);drag={pointer:e.pointerId,x:e.clientX,y:e.clientY,p:engine.position(i)};if(isPlatter)engine.startScratch(i);else{const box=el.getBoundingClientRect();el.dataset.preview=String(Math.min(1,Math.max(0,(e.clientX-box.left)/box.width)));}});el.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;const box=el.getBoundingClientRect();if(isPlatter)engine.scratchTo(i,Math.max(0,drag.p+(e.clientX-drag.x)/box.width*5));else el.dataset.preview=String(Math.min(1,Math.max(0,(e.clientX-box.left)/box.width)));});const finish=e=>{if(!drag||drag.pointer!==e.pointerId)return;if(isPlatter)engine.endScratch(i);else{const box=el.getBoundingClientRect();engine.seek(i,Math.min(1,Math.max(0,(e.clientX-box.left)/box.width))*engine.decks[i].duration);}delete el.dataset.preview;drag=null;};el.addEventListener('pointerup',finish);const cancel=e=>{if(!drag||drag.pointer!==e.pointerId)return;if(isPlatter)engine.endScratch(i);delete el.dataset.preview;drag=null;};el.addEventListener('pointercancel',cancel);el.addEventListener('lostpointercapture',cancel);el.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();if(!locked)engine.seek(i,engine.position(i)+(e.key==='ArrowRight'?1:-1));}});}}
