function enforceVideoVisibility(){if(mode!=='video'||!video.decks.some(d=>d.playing))return;const dockTop=$('#dock').getBoundingClientRect().top;for(let i=0;i<2;i++){if(!video.decks[i].playing)continue;const box=$(`#video-player-${i}`).getBoundingClientRect();if(box.width<200||box.height<200||box.top<0||box.bottom>dockTop+1){video.pauseAll();toast('Video paused because a player is out of view. Rotate the phone or scroll the player fully into view to resume.');break;}}}
