function update(){const live=state();for(let i=0;i<2;i++){const d=engine.decks[i],pos=engine.position(i);const card=$(`[data-deck="${i}"]`);card?.classList.toggle('playing',d.playing);const companion=$(`[data-companion="${i}"]`);if(companion){companion.querySelector('small').textContent=`DECK ${i+1} · ${d.playing?'PLAYING':d.track?'READY':'EMPTY'}`;const cp=companion.querySelector('[data-play]');if(cp&&cp.dataset.playing!==String(d.playing)){cp.innerHTML=playIcon(d.playing);cp.dataset.playing=String(d.playing);cp.classList.toggle('engaged',d.playing);}}const ds=$(`[data-deck-state="${i}"]`);if(ds)ds.textContent=d.scratching?'Scratching':d.playing?'Playing':d.track?'Ready':'Empty';card?.classList.toggle('scratching',!!d.scratching);const flag=$(`[data-loop-flag="${i}"]`);if(flag)flag.hidden=!d.loop;const platter=card?.querySelector('.vinyl');if(platter&&!reducedMotion())platter.style.transform=`rotate(${pos*200}deg)`;const t=$(`[data-time="${i}"]`);if(t)t.textContent=`${time(pos)} / ${time(d.duration)}`;const bpm=$(`[data-bpm="${i}"]`);if(bpm)bpm.textContent=`${d.bpm?(d.bpm*d.rate).toFixed(1):'—'} BPM`;const play=card?.querySelector('[data-play]');if(play){if(play.dataset.playing!==String(d.playing)){play.innerHTML=playIcon(d.playing);play.dataset.playing=String(d.playing);}play.classList.toggle('engaged',d.playing);play.setAttribute('aria-label',`${d.playing?'Pause':'Play'} deck ${i+1}`);}$$(`[data-meter="${i}"]`).forEach(m=>{m.style.transform=`scaleX(${Math.min(1,engine.meter(i)*1.3)})`;});const dock=$(`#dock-play-${i}`);if(dock.dataset.playing!==String(live.decks[i].playing)){dock.innerHTML=`${i?'02 ':''}${playIcon(live.decks[i].playing)}${i?'':' 01'}`;dock.dataset.playing=String(live.decks[i].playing);}dock.classList.toggle('engaged',live.decks[i].playing);const vd=video.decks[i];$(`#video-player-${i}`)?.closest('.video-card')?.setAttribute('data-state',vd.state);$(`#video-title-${i}`).textContent=vd.track?.title||(i?'Prepare the next beat':'Load your first video');$(`#video-status-${i}`).textContent=vd.error||`${vd.state||'Empty'}${vd.track?' · Player level '+Math.round(vd.volume||0)+'%':''}`;$(`#video-open-${i}`).href=vd.track?video.getURL(i):'https://www.youtube.com/';}
const x=live.crossfade??.5;if(document.activeElement!==$('#crossfader'))$('#crossfader').value=x;$('#blend-label').textContent=x<.02?'DECK 1':x>.98?'DECK 2':`BLEND · ${Math.round((1-x)*100)} / ${Math.round(x*100)}`;const playing=live.decks.filter(d=>d.playing).length;const fadeActive=!!live.fade;$('#dock').classList.toggle('fading',fadeActive);if(!$('#fade-status')){const liveRegion=document.createElement('span');liveRegion.id='fade-status';liveRegion.setAttribute('role','status');$('#dock').prepend(liveRegion);}$('#fade-status').textContent=fadeActive?'FADING · TOUCH FADER TO TAKE OVER':'';$('#dock-state').textContent=fadeActive?'FADING · MANUAL TAKEOVER':playing===2?'BOTH DECKS PLAYING':playing===1?`DECK ${live.decks[0].playing?1:2} PLAYING`:'PAUSED · READY WHEN YOU ARE';const any=engine.decks.some(d=>d.playing)||video.decks.some(d=>d.playing);if(any!==lastNativePlaying){native('playback',{playing:any});lastNativePlaying=any;}if($('#record-time'))$('#record-time').textContent=time(engine.recordingElapsed);
for(const el of $$('[data-eq]')){if(el===document.activeElement||el.closest('.rotary')?.classList.contains('adjusting'))continue;const [i,b]=el.dataset.eq.split(':');if(+el.value!==engine.decks[i].eq[b]){el.value=engine.decks[i].eq[b];syncRange(el);}}performance5.update();if(route==='waves')wave5.update();if(route==='library')library5.update();for(let i=0;i<2;i++){const d=live.decks[i];$('#dock-title-'+i).textContent=`${i+1} · ${d.track?.title||'Empty'}`;const signal=mode==='audio'?(engine.outputMeter?.(i)||0)>.001:d.playing&&d.volume>0;if(signal)audibleUntil[i]=performance.now()+180;const audible=performance.now()<audibleUntil[i]&&(mode!=='audio'||(!engine.masterMuted&&engine.master>0));$('#dock-status-'+i).textContent=d.playing?(audible?'AUDIBLE':'PLAYING · SILENT'):(d.track?'READY':'LOAD MUSIC');}for(const c of $$('[data-canvas]')){const i=+c.dataset.canvas;drawWaveform(c,engine.decks[i],i,engine.position(i),engine.waveform(i));}}

