const shortcutHolds=new Set();
window.addEventListener('keydown',e=>{if(e.key==='Escape'){close();return;}if(e.repeat||e.ctrlKey||e.altKey||e.metaKey||$('#dialog').open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable||mode!=='audio')return;const k=e.key.toLowerCase();const actions={z:()=>engine.toggle(0),m:()=>engine.toggle(1),x:()=>engine.cueDown(0),',':()=>engine.cueDown(1),a:()=>engine.bend(0,-.04),s:()=>engine.bend(0,.04),k:()=>engine.bend(1,-.04),l:()=>engine.bend(1,.04),d:()=>engine.sync(0),j:()=>engine.sync(1)};if(actions[k]){e.preventDefault();shortcutHolds.add(k);run(()=>shortcutHolds.has(k)?actions[k]():undefined);}});
function releaseShortcut(k){if(!shortcutHolds.delete(k))return;if(k==='x')engine.cueUp(0);if(k===',')engine.cueUp(1);if(['a','s'].includes(k))engine.endBend(0);if(['k','l'].includes(k))engine.endBend(1);}
